import {chestCardPdf,judgeSheetPdf,resultPosterCanvas,resultPosterPdf,saveCanvasPng,download} from './pdf.js';
import {migrateDB,parseTeams,TEAM_COLORS,PRIZE_POINTS,ledger,standings,rankByMarks} from './scores.mjs';
const $=id=>document.getElementById(id);
const KEY='meelad-desk-data-v1';
const DEFAULT_CATS=[{id:'c12',name:'Kiddies',from:1,to:2},{id:'c34',name:'Sub Junior',from:3,to:4},{id:'c57',name:'Junior',from:5,to:7},{id:'c810',name:'Senior',from:8,to:10},{id:'c1112',name:'Higher Secondary',from:11,to:12}];
const NAV={dashboard:'Overview',teams:'Teams & points',students:'Students',programs:'Programs',judges:'Judges',results:'Results',cards:'Chest cards',settings:'Settings & backup',detail:'Program details'};
const icon=(name)=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const esc=t=>String(t??'').replace(/[&<>"']/g,k=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[k]));
const slug=t=>(String(t||'meelad').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,50)||'meelad');
const uid=()=>globalThis.crypto?.randomUUID?.()||('id-'+Date.now()+'-'+Math.random().toString(36).slice(2));
const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}):'Date not set';
const pill=(text,style='gray')=>`<span class="pill ${style}">${esc(text)}</span>`;
const sortChest=(a,b)=>Number(a.chest)-Number(b.chest);
const eventIcon=(type)=>type==='On-stage'?'award':'book';
const initialDB=()=>({version:2,createdAt:new Date().toISOString(),event:{madrasaName:'',festivalName:'',date:'',place:'',madrasaLogo:'',festivalLogo:''},categories:structuredClone(DEFAULT_CATS),teams:[],counters:{program:0},students:[],judges:[],programs:[]});
let db=null;
let state={view:'dashboard',detailId:null,studentClass:'all',studentSearch:'',programCat:'all',cardClass:'all',resultCat:'all',ledgerTeam:'all'};
let modalState={};
let busy=false;
const students=()=>db.students;
const categoryForGrade=g=>db.categories.find(c=>Number(g)>=c.from&&Number(g)<=c.to);
const categoryById=id=>db.categories.find(c=>c.id===id);
const programById=id=>db.programs.find(p=>p.id===id);
const studentById=id=>db.students.find(s=>s.id===id);
const judgeById=id=>db.judges.find(j=>j.id===id);
const teamById=id=>db.teams.find(t=>t.id===id);
const teamName=s=>teamById(s?.teamId)?.name||s?.house||'Unassigned';
const teamBadge=t=>t?`<span class="team-pill"><i style="background:${esc(t.color)}"></i>${esc(t.name)}</span>`:'<span class="muted-text">Unassigned</span>';
const nextProgramCode=()=>`P${String(++db.counters.program).padStart(3,'0')}`;
function toast(text,isError=false){const el=$('toast-root');el.innerHTML=`<div class="toast ${isError?'error':''}">${icon(isError?'close':'check')}<span>${esc(text)}</span></div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.innerHTML='',4400)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch(err){toast('Device storage is full. Export a JSON backup and reduce image sizes.',true);return false}}
function nextChest(grade){const key=String(grade);const previous=Number(db.counters[key]||0);const maxExisting=db.students.filter(s=>s.grade===grade).reduce((m,s)=>Math.max(m,Number(s.roll)||0),0);const roll=Math.max(previous,maxExisting)+1;db.counters[key]=roll;let chest=grade*100+roll;if(roll>=100)chest=grade*10000+roll;return {roll,chest}}
function previewChest(grade){const key=String(grade);const next=Math.max(Number(db.counters[key]||0),...db.students.filter(s=>s.grade===Number(grade)).map(s=>s.roll||0),0)+1;return next>=100?Number(grade)*10000+next:Number(grade)*100+next}
function top(title,desc,actions='',eyebrow='FESTIVAL ADMINISTRATION'){return `<div class="page-header"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="page-title">${esc(title)}</h1><p class="page-desc">${esc(desc)}</p></div><div class="header-actions">${actions}</div></div>`}
const btn=(label,action,primary=false,ico='',extra='')=>`<button type="button" class="btn ${primary?'btn-primary':''}" data-action="${action}" ${extra}>${ico?icon(ico):''}${esc(label)}</button>`;
const empty=(name,msg,action='',cta='')=>`<div class="empty"><div class="empty-icon">${icon('file')}</div><strong>${esc(name)}</strong><p>${esc(msg)}</p>${action?btn(cta,action,true,'plus'):''}</div>`;
function go(view,detailId){state.view=view;state.detailId=detailId||null;render();window.scrollTo(0,0);$('sidebar').classList.remove('open');$('mobile-shade').classList.remove('show')}
function render(){
  if(!db){$('workspace').classList.add('hidden');showSetup();return}
  $('setup-root').innerHTML='';$('workspace').classList.remove('hidden');
  $('sidebar-event').innerHTML=`<div class="side-overline">ACTIVE FESTIVAL</div><strong>${esc(db.event.festivalName)}</strong><small>${esc(db.event.madrasaName)} · ${db.teams.length} teams</small>`;
  document.querySelectorAll('[data-view]').forEach(el=>el.classList.toggle('active',el.dataset.view===state.view||(state.view==='detail'&&el.dataset.view==='programs')));
  $('breadcrumbs').innerHTML=`Workspace <span class="crumb-slash">/</span> <b>${esc(NAV[state.view]||'Overview')}</b>`;
  $('app').innerHTML=({dashboard:viewDashboard,teams:viewTeams,students:viewStudents,programs:viewPrograms,judges:viewJudges,results:viewResults,cards:viewCards,settings:viewSettings,detail:viewDetail}[state.view]||viewDashboard)();
}
function logoField(label,name,current){return `<div class="field-wrap"><label class="field-label" for="${name}">${esc(label)}</label><div class="upload-box">${current?`<img class="upload-preview" src="${esc(current)}" alt="Current logo">`:`<div class="upload-preview" style="display:grid;place-content:center;color:#98aa9c">${icon('upload')}</div>`}<div style="min-width:0;flex:1"><input class="file-input" type="file" id="${name}" name="${name}" accept="image/*"><small>PNG, JPG or SVG · optional · max 3 MB</small></div></div>${current?`<label class="checkbox-inline" style="margin-top:7px"><input type="checkbox" name="clear-${name}"> Remove current logo</label>`:''}</div>`}
function eventFields(event){return `<div class="form-grid"><div class="field-wrap"><label class="field-label">Madrasa name *</label><input class="field" name="madrasaName" required maxlength="110" placeholder="e.g. Misbahul Huda Madrasa" value="${esc(event.madrasaName)}"></div><div class="field-wrap"><label class="field-label">Meelad / festival name *</label><input class="field" name="festivalName" required maxlength="110" placeholder="e.g. Ishqotsav 2026" value="${esc(event.festivalName)}"></div><div class="field-wrap"><label class="field-label">Festival date</label><input class="field" type="date" name="date" value="${esc(event.date)}"></div><div class="field-wrap"><label class="field-label">Place / venue</label><input class="field" name="place" maxlength="110" placeholder="e.g. Chakkarakkal" value="${esc(event.place)}"></div>${logoField('Madrasa logo','madrasaLogo',event.madrasaLogo)}${logoField('Meelad logo','festivalLogo',event.festivalLogo)}</div>`}
function showSetup(){const el=$('setup-root');el.innerHTML=`<div class="setup-screen"><section class="setup-art"><div class="setup-logo">meelad desk<span>.</span></div><div><h1>One festival.<br>Many talents.<br><em>One place.</em></h1><p>Register students, coordinate competitions, tally team points and celebrate each result — completely offline.</p></div><small>Designed for the people who make Meelad happen.</small></section><section class="setup-form-side"><div class="setup-form"><div class="setup-step">STEP 01 / FESTIVAL SETUP</div><h2 class="page-title" style="margin-top:13px">Set up your Meelad.</h2><p class="page-desc">No account required. Start with your event and its competing teams; everything can be edited later.</p><form id="setup-form">${eventFields({madrasaName:'',festivalName:'',date:'',place:'',madrasaLogo:'',festivalLogo:''})}<div class="team-setup-block"><div class="section-head"><h3 class="section-title">Competing teams <span class="required-asterisk">*</span></h3>${pill('5 / 3 / 1 points')}</div><p class="hint">Add your actual team names, one per line or separated by commas. You can rename or add teams later.</p><textarea class="field team-textarea" name="teams" rows="3" required placeholder="Team 1&#10;Team 2"></textarea></div><div style="margin-top:25px;display:flex;justify-content:flex-end"><button class="btn btn-primary" type="submit">Create workspace ${icon('arrow')}</button></div></form><div class="setup-micro">Includes class-based chest codes and JSON backup/restore.</div></div></section></div>`}
function stat(label,value,footer,ico){return `<article class="stat-card"><div class="stat-icon">${icon(ico)}</div><div class="stat-label">${label}</div><div class="stat-value">${value}</div><p class="stat-footer">${footer}</p></article>`}
function viewDashboard(){const enrolled=db.programs.reduce((a,p)=>a+p.participants.length,0);const withResults=db.programs.filter(p=>p.result?.published).length;const recent=[...db.programs].reverse().slice(0,5);return top('Festival overview',`Welcome to ${db.event.festivalName}. Here's what's happening across your workspace.`,btn('Add student','add-student',true,'plus')+btn('New program','add-program',false,'plus'))+
`<div class="stats-grid">${stat('Registered students',db.students.length,'Across '+db.categories.length+' categories','users')}${stat('Festival programs',db.programs.length,'Scheduled competitions','book')}${stat('Program entries',enrolled,'Total participant registrations','cards')}${stat('Published results',withResults,db.programs.length?`${db.programs.length-withResults} awaiting publication`:'No results yet','award')}</div>
${dashboardTeams()}<div class="content-grid"><section class="panel"><div class="panel-head"><div><h2>Recent programs</h2><p>Quick access to your competition roster</p></div><button class="link-button" data-view="programs">View all ${icon('arrow')}</button></div>${recent.length?`<div class="item-list">${recent.map(p=>`<div class="list-row"><div class="list-icon">${icon(eventIcon(p.type))}</div><div class="list-main"><strong>${esc(p.name)}</strong><small>${esc(p.code)} · ${esc(categoryById(p.categoryId)?.name||'Uncategorised')} · ${p.participants.length} participants</small></div><div class="list-end">${p.result?.published?pill('Published'):pill('In progress','sand')}<button class="icon-button" data-action="detail" data-id="${p.id}" aria-label="Open program">${icon('chevron')}</button></div></div>`).join('')}</div>`:empty('No programs yet','Create a competition, choose a category and add registered students.','add-program','Create program')}</section>
<section class="stack"><section class="panel panel-pad"><div class="section-head"><h2 class="section-title">Quick actions</h2>${pill('Get started')}</div><div class="quick-actions"><button class="quick-action" data-action="add-student">${icon('users')} Register student</button><button class="quick-action" data-action="add-program">${icon('plus')} Add a program</button><button class="quick-action" data-view="cards">${icon('cards')} Chest cards</button><button class="quick-action" data-action="judge-all">${icon('printer')} Judge sheets</button></div></section><section class="panel panel-pad"><h2 class="section-title">Registration by category</h2><div style="margin-top:20px">${db.categories.map(c=>{const count=db.students.filter(s=>categoryForGrade(s.grade)?.id===c.id).length;const max=Math.max(1,...db.categories.map(cat=>db.students.filter(s=>categoryForGrade(s.grade)?.id===cat.id).length));return `<div style="margin-bottom:18px"><div class="row-between"><span style="font-size:12px;font-weight:650">${esc(c.name)} <span class="muted-text">· ${c.from}–${c.to}</span></span><strong style="font-size:12px">${count}</strong></div><div class="kpi-line"><span style="width:${count/max*100}%"></span></div></div>`}).join('')}</div></section><div class="note"><strong>Private by design</strong>Everything is stored in this browser. Export a backup regularly, especially before switching computers or clearing browser data.</div></section></div>`}
function dashboardTeams(){
 const teams=standings(db),total=ledger(db).reduce((s,x)=>s+x.points,0);
 return `<section class="team-overview panel"><div class="panel-head"><div><div class="eyebrow">LIVE TEAM STANDINGS</div><h2>Team points</h2><p>Automatically calculated from published first, second and third places</p></div><button class="btn btn-sm" data-view="teams">Full point ledger ${icon('arrow')}</button></div><div class="team-strip">${teams.length?teams.map((t,i)=>`<div class="team-strip-item"><div class="team-strip-top"><span class="team-ordinal">${String(i+1).padStart(2,'0')}</span>${teamBadge(t)}</div><div class="team-strip-points">${t.points}<span> pts</span></div><div class="team-strip-bottom"><span>${t.first} firsts · ${t.second} seconds · ${t.third} thirds</span><div class="team-track"><i style="width:${total?t.points/Math.max(total,1)*100:0}%;background:${esc(t.color)}"></i></div></div></div>`).join(''):'<div class="panel-pad"><p class="page-desc">Add your teams in Settings to start tracking points.</p></div>'}</div><div class="team-score-rule"><span>SCORING</span><strong>1st <b>+5</b></strong><strong>2nd <b>+3</b></strong><strong>3rd <b>+1</b></strong><small>Draft results do not count.</small></div></section>`;
}
function viewTeams(){
 const teams=standings(db),all=ledger(db),filtered=all.filter(x=>state.ledgerTeam==='all'||x.teamId===state.ledgerTeam);
 const total=all.reduce((s,x)=>s+x.points,0);
 return top('Teams & points','A transparent scorebook for every program and every prize. Totals update automatically when published results change.',btn('Add team','add-team',true,'plus'))+
 `<div class="stats-grid score-stats">${stat('Total team points',total,'Across '+all.length+' awarded prizes','award')}${stat('Published programs',db.programs.filter(p=>p.result?.published).length,'Only published results contribute','book')}${stat('Competing teams',teams.length,'Manage teams below','users')}${stat('Point rules','5 / 3 / 1','First · Second · Third','grid')}</div>
 <section class="panel" style="margin-bottom:20px"><div class="panel-head"><div><h2>Standings</h2><p>Highest points first; tied totals favour more first places</p></div></div><div class="standings-list">${teams.map((t,i)=>`<div class="standing-row"><div class="standing-position">${String(i+1).padStart(2,'0')}</div>${teamBadge(t)}<div class="standing-breakdown"><span>${t.first} × 1st</span><span>${t.second} × 2nd</span><span>${t.third} × 3rd</span></div><div class="standing-points">${t.points}<small>points</small></div><div class="table-actions"><button class="icon-button" data-action="edit-team" data-id="${t.id}" title="Edit team">${icon('edit')}</button><button class="icon-button danger" data-action="delete-team" data-id="${t.id}" title="Delete unused team">${icon('trash')}</button></div></div>`).join('')||empty('No teams yet','Add a team to create a standings table.','add-team','Add team')}</div></section>
 <section class="panel"><div class="panel-head"><div><h2>Point breakdown</h2><p>Every contribution, with its program, winning chest code and award</p></div><select id="ledger-team-filter" class="mini-select"><option value="all">All teams</option>${db.teams.map(t=>`<option value="${t.id}" ${state.ledgerTeam===t.id?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div>${filtered.length?`<div class="table-shell"><table class="data-table"><thead><tr><th>Program</th><th>Category</th><th>Team</th><th>Winner / code</th><th>Prize</th><th style="text-align:right">Points</th></tr></thead><tbody>${filtered.map(r=>`<tr><td><strong>${esc(r.program)}</strong><div class="muted-text">${esc(r.code)} · ${esc(fmt(r.date))}</div></td><td>${esc(r.category)}</td><td>${teamBadge(teamById(r.teamId))}</td><td>${esc(r.student)} <span class="code-pill">${r.chest}</span></td><td>${['','1st','2nd','3rd'][r.rank]}</td><td class="point-cell">+${r.points}</td></tr>`).join('')}</tbody></table></div>`:empty('No awarded points yet','Publish a program result with winning chest codes to populate this ledger.')}</section>
 <div class="note score-note"><strong>Points are never entered manually.</strong>Editing or unpublishing a result immediately changes this table. Deleting a student or program also removes its contribution.</div>`;
}
function settingsTeams(){return `<section class="panel"><div class="panel-head"><div><h2>Competing teams</h2><p>Rename teams or add new ones without changing earned points</p></div><button class="btn btn-sm" data-action="add-team">${icon('plus')} Add team</button></div>${db.teams.map(t=>`<div class="category-row">${teamBadge(t)}<span class="count-label" style="margin-left:auto">${db.students.filter(s=>s.teamId===t.id).length} students</span><button class="icon-button" title="Edit team" data-action="edit-team" data-id="${t.id}">${icon('edit')}</button><button class="icon-button" title="Delete unused team" data-action="delete-team" data-id="${t.id}">${icon('trash')}</button></div>`).join('')||'<div class="panel-pad"><p class="page-desc">No teams have been set up.</p></div>'}</section>`}
function teamModal(id){const t=id?teamById(id):null;if(id&&!t)return;modal(t?'Edit team':'Add team','Set the name that appears in standings and chest cards.',`<div class="form-grid"><div class="full"><label class="field-label">Team name *</label><input class="field" name="name" required maxlength="65" value="${esc(t?.name||'')}" placeholder="Your team name"></div><div class="full"><label class="field-label">Team colour</label><input class="team-color-input" name="color" type="color" value="${t?.color||TEAM_COLORS[db.teams.length%TEAM_COLORS.length]}"></div></div>`);modalState={kind:'team',id};}
function showWinnerHints(){const p=programById(modalState.id);if(!p)return;for(const el of document.querySelectorAll('.winner-code')){const rank=Number(el.name.replace('place','')),hint=document.querySelector(`.winner-hint[data-rank="${rank}"]`),chest=el.value.trim();if(!hint)continue;const s=p.participants.map(studentById).find(s=>s&&String(s.chest)===chest);hint.textContent=!chest?'Optional unless publishing without other places':s?`${s.name} · ${teamName(s)}`:'Not found in this program';hint.classList.toggle('error-text',Boolean(chest&&!s))}}
function classOptions(selected='all',includeAll=true){return `${includeAll?`<option value="all" ${selected==='all'?'selected':''}>All classes</option>`:''}${Array.from({length:12},(_,i)=>i+1).map(x=>`<option value="${x}" ${String(selected)===String(x)?'selected':''}>Class ${x}</option>`).join('')}`}
function catOptions(selected='all',includeAll=true){return `${includeAll?`<option value="all" ${selected==='all'?'selected':''}>All categories</option>`:''}${db.categories.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)} · ${c.from}–${c.to}</option>`).join('')}`}
function viewStudents(){const list=db.students.filter(s=>state.studentClass==='all'||String(s.grade)===String(state.studentClass)).sort((a,b)=>a.grade-b.grade||sortChest(a,b));return top('Students','Register, organise and manage your student roster. Chest numbers are generated automatically.',btn('Add student','add-student',true,'plus'))+`<section class="panel"><div class="toolbar"><div class="search-field">${icon('search')}<input aria-label="Search students" id="student-search" placeholder="Search by name, chest or team..." value="${esc(state.studentSearch)}"></div><select id="student-filter" class="mini-select" aria-label="Filter class">${classOptions(state.studentClass)}</select><span class="count-label">${list.length} students</span></div>${db.students.length?`<div class="table-shell"><table class="data-table"><thead><tr><th>Chest no.</th><th>Student</th><th>Class</th><th>Category</th><th>Team</th><th style="text-align:right">Actions</th></tr></thead><tbody>${list.map(s=>`<tr data-search="${esc((s.name+' '+s.chest+' '+teamName(s)).toLowerCase())}"><td><span class="code-pill">${s.chest}</span></td><td class="main-cell">${esc(s.name)}</td><td>Class ${s.grade}</td><td>${pill(categoryForGrade(s.grade)?.name||'—')}</td><td>${teamBadge(teamById(s.teamId))}</td><td><div class="table-actions"><button class="icon-button" title="Download chest card" data-action="card-one" data-id="${s.id}">${icon('download')}</button><button class="icon-button" title="Edit student" data-action="edit-student" data-id="${s.id}">${icon('edit')}</button><button class="icon-button danger" title="Delete student" data-action="delete-student" data-id="${s.id}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Your roster is empty','Register your first student. Their chest number will be assigned from their class.','add-student','Register student')}<div id="student-no-match" class="hidden" style="padding:20px;color:#8a958a">No students match that search.</div></section>`}
function viewPrograms(){const list=db.programs.filter(p=>state.programCat==='all'||p.categoryId===state.programCat);return top('Programs','Create events, assign participants and judges, and print competition sheets.',btn('Bulk judge sheets','judge-all',false,'download')+btn('New program','add-program',true,'plus'))+`<section class="panel"><div class="toolbar"><div class="search-field">${icon('search')}<input id="program-search" aria-label="Search programs" placeholder="Find a program..."></div><select id="program-filter" class="mini-select">${catOptions(state.programCat)}</select><span class="count-label">${list.length} programs</span></div>${list.length?`<div class="table-shell"><table class="data-table"><thead><tr><th>Program</th><th>Category</th><th>Participants</th><th>Judges</th><th>Status</th><th style="text-align:right">Actions</th></tr></thead><tbody>${list.map(p=>`<tr data-search="${esc(p.name.toLowerCase())}"><td><button class="link-button main-cell" data-action="detail" data-id="${p.id}">${esc(p.name)} ${icon('chevron')}</button><div class="muted" style="font-size:11px;margin-top:5px">${esc(p.code)} · ${esc(p.type)} · ${esc(fmt(p.date))}</div></td><td>${esc(categoryById(p.categoryId)?.name||'—')}</td><td>${p.participants.length}</td><td>${p.judges.length}</td><td>${p.result?.published?pill('Published'):p.result?pill('Draft result','sand'):pill('Awaiting result','gray')}</td><td><div class="table-actions"><button class="icon-button" title="Download judge sheet" data-action="judge-one" data-id="${p.id}">${icon('download')}</button><button class="icon-button" title="Edit program" data-action="edit-program" data-id="${p.id}">${icon('edit')}</button><button class="icon-button danger" title="Delete program" data-action="delete-program" data-id="${p.id}">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('No matching programs','Set up a program and assign students from the relevant category.','add-program','Create program')}</section>`}
function viewJudges(){return top('Judges','Maintain a judge directory and assign judges to individual programs.',btn('Add judge','add-judge',true,'plus'))+`<section class="panel">${db.judges.length?`<div class="table-shell"><table class="data-table"><thead><tr><th>Judge</th><th>Role / designation</th><th>Assigned programs</th><th style="text-align:right">Actions</th></tr></thead><tbody>${db.judges.map(j=>`<tr><td class="main-cell">${esc(j.name)}</td><td class="muted">${esc(j.role||'—')}</td><td>${db.programs.filter(p=>p.judges.includes(j.id)).length}</td><td><div class="table-actions"><button class="icon-button" data-action="edit-judge" data-id="${j.id}" title="Edit">${icon('edit')}</button><button class="icon-button danger" data-action="delete-judge" data-id="${j.id}" title="Delete">${icon('trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:empty('Add your judging team','Create judge profiles and assign them when setting up a program.','add-judge','Add judge')}</section>`}
function viewDetail(){const p=programById(state.detailId);if(!p)return '<p>Program not found.</p>';const cat=categoryById(p.categoryId);const roster=p.participants.map(studentById).filter(Boolean).sort(sortChest);const judges=p.judges.map(judgeById).filter(Boolean);const places=p.result?.places||{};return `<button class="detail-back" data-view="programs">${icon('arrow')} Back to all programs</button>`+top(p.name,`Program ${p.code} · Manage registration, judging and results.`,btn('Judge sheet PDF','judge-one',false,'download',`data-id="${p.id}"`)+btn('Enter results','result-edit',false,'award',`data-id="${p.id}"`)+btn('Edit program','edit-program',true,'edit',`data-id="${p.id}"`),'PROGRAM DETAILS')+`<div class="detail-meta"><span>${icon('book')} ${esc(cat?.name||'Uncategorised')}</span><span>${icon('calendar')} ${esc(fmt(p.date))}</span><span>${icon('grid')} ${esc(p.type)}</span><span>${icon('users')} ${roster.length} participants</span><span>${icon('gavel')} ${judges.length} judges</span></div><div class="two-col"><section class="panel"><div class="panel-head"><div><h2>Registered participants</h2><p>Official chest numbers for this program</p></div><button class="btn btn-sm" data-action="edit-program" data-id="${p.id}">${icon('edit')} Edit roster</button></div>${roster.length?`<div class="table-shell"><table class="data-table"><thead><tr><th>Chest no.</th><th>Name</th><th>Class</th><th>Team</th></tr></thead><tbody>${roster.map(s=>`<tr><td><span class="code-pill">${s.chest}</span></td><td class="main-cell">${esc(s.name)}</td><td>${s.grade}</td><td class="muted">${esc(teamName(s))}</td></tr>`).join('')}</tbody></table></div>`:empty('No participants assigned','Edit this program to register eligible students.')}</section><section class="stack"><section class="panel panel-pad"><div class="section-head"><h2 class="section-title">Assigned judges</h2>${pill(judges.length+' total')}</div>${judges.length?judges.map(j=>`<div class="winner-row"><div class="list-icon">${icon('gavel')}</div><div><strong>${esc(j.name)}</strong><div class="muted-text" style="font-size:11px">${esc(j.role||'Judge')}</div></div></div>`).join(''):'<p class="page-desc">No judges assigned. Edit the program to select judges.</p>'}</section><section class="panel panel-pad"><div class="section-head"><h2 class="section-title">Results</h2>${p.result?(p.result.published?pill('Published'):pill('Draft','sand')):pill('Not entered','gray')}</div>${p.result?`<div>${[1,2,3].map(i=>{const s=studentById(places[i]);return `<div class="winner-row"><span class="rank ${i===2?'second':i===3?'third':''}">${i}</span><div><strong style="font-size:12px">${esc(s?.name||'Not assigned')}</strong><div class="muted-text" style="font-size:11px">${s?'Chest '+s.chest:'—'}</div></div></div>`}).join('')}</div><div class="inline-actions" style="margin-top:18px">${btn('Poster PDF','poster-pdf',false,'download',`data-id="${p.id}"`)}${btn('Print','poster-print',false,'printer',`data-id="${p.id}"`)}${p.result.attachment?btn('Attached result','attachment-download',false,'file',`data-id="${p.id}"`):''}</div>`:`<p class="page-desc">Record winners to generate a personalised result poster.</p><div style="margin-top:17px">${btn('Enter results','result-edit',false,'award',`data-id="${p.id}"`)}</div>`}</section></section></div>`}
function viewResults(){const list=db.programs.filter(p=>state.resultCat==='all'||p.categoryId===state.resultCat);return top('Results & posters','Enter judge marks by chest code, publish results, award team points and create printable posters.',btn('Download all published posters','posters-all',false,'download'))+`<section class="panel"><div class="toolbar"><span class="count-label">${db.programs.filter(p=>p.result?.published).length} published of ${db.programs.length} programs</span><select id="result-filter" class="mini-select">${catOptions(state.resultCat)}</select></div>${list.length?list.map(p=>`<div class="prog-tile"><div><div class="main-cell">${esc(p.name)}</div><small>${esc(p.code)} · ${esc(categoryById(p.categoryId)?.name||'—')} · ${p.participants.length} participants</small></div><div class="right">${p.result?.published?pill('Published'):p.result?pill('Draft','sand'):pill('No result','gray')}<button class="btn btn-sm" data-action="result-edit" data-id="${p.id}">${icon('edit')} ${p.result?'Edit result':'Enter result'}</button>${p.result?`<button class="btn btn-sm" data-action="poster-preview" data-id="${p.id}">${icon('award')} Poster</button>`:''}</div></div>`).join(''):empty('No programs to show','Add a program before recording its results.','add-program','Create program')}</section>`}
